function sp = load_species()
%LOAD_SPECIES  Read NASA-7 data (GRI-Mech 3.0) from data/nasa7_species.json.
%   The file is generated by scripts/export_matlab_reference.py (Python/Cantera).
%   The result is cached after the first call.

persistent cache
if isempty(cache)
    here = fileparts(mfilename('fullpath'));            % .../matlab/src/thermo
    f = fullfile(here, '..', '..', 'data', 'nasa7_species.json');
    if ~isfile(f)
        error('load_species:missing', 'Data file not found: %s', f);
    end
    cache = jsondecode(fileread(f));

    c = pbmr_const();
    if ~isequal(cache.names(:)', c.species)
        error('load_species:order', 'Species order in JSON differs from pbmr_const.');
    end
end
sp = cache;
end
